  const invalid = () => {
    const error = new Error(
      "Branch display history is incomplete or inconsistent",
    );
    error.code = "SESSION_BRANCH_HISTORY_INVALID";
    throw error;
  };
  const require = (condition) => {
    if (!condition) invalid();
  };

